using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class DiscountScenarioTests
{
    private static LoyaltyDiscountQuote Quote(int subtotal, LoyaltyTier tier, string? code = null) =>
        new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotal, tier, code));

    private static void AssertQuote(LoyaltyDiscountQuote q, int discount, int total)
    {
        Assert.Equal(discount, q.DiscountCents);
        Assert.Equal(total, q.TotalCents);
    }

    [Theory]
    [InlineData(20_000, LoyaltyTier.Gold, 2_000, 18_000)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_000, 28_000)]
    [InlineData(12_000, LoyaltyTier.Gold, 1_800, 10_200)]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(subtotal, tier), discount, total);

    [Theory]
    [InlineData(2_999, 0, 2_999)]
    [InlineData(3_000, 450, 2_550)]
    public void S3_NoLoyaltyDiscountUnderThirtyEuros(int subtotal, int discount, int total) =>
        AssertQuote(Quote(subtotal, LoyaltyTier.Gold), discount, total);

    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, 1_500, 8_500)]
    [InlineData(2_000, LoyaltyTier.Bronze, 500, 1_500)]
    public void S4_Welcome5TakesFiveEurosAfterLoyaltyDiscount(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, total);

    [Theory]
    [InlineData(20_000, LoyaltyTier.Gold, 2_500, 17_500)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_500, 27_500)]
    public void S5_CapAppliesToLoyaltyDiscountOnly(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, total);

    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        Assert.Equal(1_500, Quote(10_000, LoyaltyTier.Silver, code).DiscountCents);

    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, 1_900, 8_100)]
    [InlineData(30_000, LoyaltyTier.Bronze, 3_000, 27_000)]
    [InlineData(2_000, LoyaltyTier.Gold, 200, 1_800)]
    public void S7_Summer10TakesTenPercentOfWhatIsLeftAtMostFifteenEuros(int subtotal, LoyaltyTier tier, int discount, int total) =>
        AssertQuote(Quote(subtotal, tier, "SUMMER10"), discount, total);

    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        AssertQuote(Quote(10_000, LoyaltyTier.Silver, "SPRING"), 1_000, 9_000);

    [Theory]
    [InlineData(10_000, 2_000, 8_000)]
    [InlineData(5_000, 1_000, 4_000)]
    [InlineData(20_000, 2_000, 18_000)]
    public void S9_PlatinumMembersReceiveTwentyPercent(int subtotal, int discount, int total) =>
        AssertQuote(Quote(subtotal, LoyaltyTier.Platinum), discount, total);

    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, 400)]
    [InlineData(300, LoyaltyTier.Gold, 300)]
    public void S10_DiscountNeverExceedsSubtotal(int subtotal, LoyaltyTier tier, int discount) =>
        AssertQuote(Quote(subtotal, tier, "WELCOME5"), discount, 0);

    private static int Standard(int payable, LoyaltyTier tier) =>
        new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payable, tier));

    [Theory]
    [InlineData(4_999, LoyaltyTier.Bronze, 490)]
    [InlineData(5_000, LoyaltyTier.Bronze, 0)]
    [InlineData(4_999, LoyaltyTier.Silver, 490)]
    public void S11_StandardShippingIsFreeFromFiftyEurosPayable(int payable, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, Standard(payable, tier));

    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(0, Standard(1_000, tier));

    [Theory]
    [InlineData(10_000, LoyaltyTier.Bronze, 990)]
    [InlineData(1_000, LoyaltyTier.Gold, 990)]
    [InlineData(1_000, LoyaltyTier.Platinum, 0)]
    public void S13_ExpressShippingCostsNinetyNineExceptForPlatinum(int payable, LoyaltyTier tier, int fee) =>
        Assert.Equal(fee, new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payable, tier, true)));

    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, "WELCOME5", false, 8_500, 0, 8_500)]
    [InlineData(5_000, LoyaltyTier.Bronze, null, false, 4_750, 490, 5_240)]
    [InlineData(20_000, LoyaltyTier.Platinum, "SUMMER10", true, 16_500, 0, 16_500)]
    [InlineData(2_000, LoyaltyTier.Gold, null, true, 2_000, 990, 2_990)]
    public void S14_CheckoutQuoteAddsShippingToPayableTotal(
        int subtotal, LoyaltyTier tier, string? code, bool express, int payable, int fee, int total) =>
        Assert.Equal(
            new CheckoutQuote(payable, fee, total),
            new QuoteCheckout().Handle(new QuoteCheckoutQuery(subtotal, tier, code, express)));
}
E
