using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class LoyaltyDiscountPolicyTests
{
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 3_001, 150)]
    [InlineData(LoyaltyTier.Silver, 3_001, 300)]
    [InlineData(LoyaltyTier.Gold, 3_001, 450)]
    [InlineData(LoyaltyTier.Bronze, 3_007, 150)]
    [InlineData(LoyaltyTier.Silver, 3_007, 300)]
    [InlineData(LoyaltyTier.Gold, 3_007, 451)]
    [InlineData(LoyaltyTier.Bronze, 10_000, 500)]
    [InlineData(LoyaltyTier.Silver, 10_000, 1_000)]
    [InlineData(LoyaltyTier.Gold, 10_000, 1_500)]
    public void DiscountIsTheTierRateRoundedDownToTheCent(
        LoyaltyTier tier, int subtotalCents, int expectedDiscountCents)
    {
        Assert.Equal(expectedDiscountCents, LoyaltyDiscountPolicy.DiscountCents(subtotalCents, tier));
    }
}

